-- customer_db for customer-service
-- Includes customer, channel_profile, beneficiary, kyc, and kyc_update_request


-- 1. CUSTOMER TABLE
IF OBJECT_ID(N'customer', N'U') IS NULL
CREATE TABLE customer (
    customer_id BIGINT IDENTITY(1,1) PRIMARY KEY,
    kyc_status VARCHAR(20) NOT NULL DEFAULT 'VERIFIED',
    created_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME()
);

-- 2. CHANNEL_PROFILE TABLE
IF OBJECT_ID(N'channel_profile', N'U') IS NULL
CREATE TABLE channel_profile (
    customer_id BIGINT PRIMARY KEY REFERENCES customer(customer_id),
    membership_number VARCHAR(20) NOT NULL UNIQUE,
    username VARCHAR(100) NOT NULL UNIQUE,
    display_name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL,
    preferred_language VARCHAR(10) NOT NULL DEFAULT 'en',
    kyc_tier VARCHAR(20) NOT NULL,
    kyc_status VARCHAR(20) NOT NULL DEFAULT 'VERIFIED',
    risk_score NUMERIC(4, 2) NOT NULL CHECK (risk_score BETWEEN 0 AND 1),
    credit_score INT NOT NULL CHECK (credit_score BETWEEN 300 AND 850),
    daily_limit NUMERIC(18, 4) NOT NULL,
    created_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME()
);

-- 3. KYC TABLE (Master Legal Record)
IF OBJECT_ID(N'kyc', N'U') IS NULL
CREATE TABLE kyc (
    kyc_id BIGINT IDENTITY(1000,1) PRIMARY KEY,
    customer_id BIGINT NOT NULL UNIQUE REFERENCES customer(customer_id),
    first_name VARCHAR(100) NOT NULL,
    middle_initial VARCHAR(10),
    last_name VARCHAR(100) NOT NULL,
    address VARCHAR(255) NOT NULL,
    civil_status VARCHAR(50),
    occupation VARCHAR(100),
    mobile_number VARCHAR(30) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'VERIFIED',
    created_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME()
);

-- 4. KYC_UPDATE_REQUEST TABLE
IF OBJECT_ID(N'kyc_update_request', N'U') IS NULL
CREATE TABLE kyc_update_request (
    kyc_request_id BIGINT IDENTITY(1000,1) PRIMARY KEY,
    kyc_id BIGINT NOT NULL REFERENCES kyc(kyc_id),
    new_first_name VARCHAR(100),
    new_middle_initial VARCHAR(10),
    new_last_name VARCHAR(100),
    new_address VARCHAR(255),
    new_mobile_number VARCHAR(30),
    new_civil_status VARCHAR(50),
    new_occupation VARCHAR(100),
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    approved_by BIGINT,
    requested_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
    approved_at DATETIME2(6)
);

-- 5. BENEFICIARY TABLE
IF OBJECT_ID(N'beneficiary', N'U') IS NULL
CREATE TABLE beneficiary (
    beneficiary_id BIGINT IDENTITY(1,1) PRIMARY KEY,
    customer_id BIGINT NOT NULL REFERENCES channel_profile(customer_id),
    account_number VARCHAR(34) NOT NULL,
    nickname VARCHAR(60) NOT NULL,
    bank_code VARCHAR(8) NOT NULL,
    active BIT NOT NULL DEFAULT 1,
    created_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
    UNIQUE (customer_id, account_number, bank_code)
);

